-- Space Exploration & Astronomy History Enrichment
-- ~30 new events + ~20 causality links

-- ANCIENT ASTRONOMY
INSERT INTO events (slug, title, date_earliest, date_latest, year_approx, is_bce, article_summary, event_category, region, importance_score, geo_modern, geo_era_label, geo_point, review_status, created_by) VALUES
('stonehenge-astronomical-calendar', 'Stonehenge Constructed as Astronomical Calendar', '2500-01-01', '2500-12-31', -2500, true, 'Stonehenge, a prehistoric monument in Wiltshire, England, was built over several stages beginning around 3000 BCE. Its alignment with solstices and equinoxes suggests it served as an astronomical calendar and ceremonial site.', 'science', 'Europe', 0.70, 'United Kingdom', 'Bronze Age Britain', ST_SetSRID(ST_MakePoint(-1.8262, 51.1789), 4326), 'approved', 'enrichment:space-astronomy'),
('babylonian-eclipse-prediction', 'Babylonian Astronomy — Prediction of Eclipses', '0700-01-01', '0700-12-31', -700, true, 'Babylonian astronomers developed sophisticated methods for predicting lunar and solar eclipses using systematic observation records spanning centuries. Their astronomical diaries are among the earliest scientific documents.', 'science', 'Middle East', 0.65, 'Iraq', 'Neo-Babylonian Empire', ST_SetSRID(ST_MakePoint(44.4209, 32.5427), 4326), 'approved', 'enrichment:space-astronomy'),
('eratosthenes-earth-circumference', 'Eratosthenes Measures Earth''s Circumference', '0240-01-01', '0240-12-31', -240, true, 'Greek mathematician Eratosthenes calculated Earth''s circumference with remarkable accuracy by comparing shadow angles at Alexandria and Syene during the summer solstice, arriving at approximately 40,000 km.', 'discovery', 'Middle East', 0.75, 'Egypt', 'Ptolemaic Egypt', ST_SetSRID(ST_MakePoint(29.9187, 31.2001), 4326), 'approved', 'enrichment:space-astronomy'),
('ptolemy-almagest-geocentric', 'Ptolemy Codifies Geocentric Model — Almagest', '0150-01-01', '0150-12-31', 150, false, 'Claudius Ptolemy published the Almagest, a comprehensive treatise on astronomy that codified the geocentric model of the universe. It remained the dominant astronomical framework for over 1,300 years.', 'science', 'Middle East', 0.70, 'Egypt', 'Roman Egypt', ST_SetSRID(ST_MakePoint(29.9187, 31.2001), 4326), 'approved', 'enrichment:space-astronomy'),
('al-battani-astronomical-measurements', 'Al-Battani — Precise Astronomical Measurements', '0880-01-01', '0880-12-31', 880, false, 'Al-Battani, a Syrian Arab astronomer, made remarkably precise astronomical measurements including the length of the solar year and the obliquity of the ecliptic. His work influenced Copernicus and Kepler centuries later.', 'science', 'Middle East', 0.60, 'Syria', 'Abbasid Caliphate', ST_SetSRID(ST_MakePoint(38.9637, 36.3489), 4326), 'approved', 'enrichment:space-astronomy')
ON CONFLICT (slug) DO NOTHING;

-- SCIENTIFIC REVOLUTION (only missing ones)
INSERT INTO events (slug, title, date_earliest, date_latest, year_approx, is_bce, article_summary, event_category, region, importance_score, geo_modern, geo_era_label, geo_point, review_status, created_by) VALUES
('halley-predicts-comet-return', 'Halley Predicts Comet Return', '1705-01-01', '1705-12-31', 1705, false, 'Edmond Halley used Newton''s gravitational theory to calculate the orbit of the great comet of 1682, predicting its return in 1758. Its appearance as predicted was a triumphant confirmation of Newtonian physics.', 'science', 'Europe', 0.65, 'United Kingdom', 'Early Modern Britain', ST_SetSRID(ST_MakePoint(-0.1278, 51.5074), 4326), 'approved', 'enrichment:space-astronomy'),
('herschel-discovers-uranus', 'Herschel Discovers Uranus', '1781-03-13', '1781-03-13', 1781, false, 'William Herschel discovered Uranus using a homemade telescope, the first planet found since antiquity. This doubled the known size of the solar system and demonstrated the power of telescopic observation.', 'discovery', 'Europe', 0.70, 'United Kingdom', 'Georgian Britain', ST_SetSRID(ST_MakePoint(-2.3590, 51.3811), 4326), 'approved', 'enrichment:space-astronomy')
ON CONFLICT (slug) DO NOTHING;

-- MODERN SPACE AGE
INSERT INTO events (slug, title, date_earliest, date_latest, year_approx, is_bce, article_summary, event_category, region, importance_score, geo_modern, geo_era_label, geo_point, review_status, created_by) VALUES
('tsiolkovsky-rocket-equation', 'Tsiolkovsky Publishes Rocket Equation', '1903-01-01', '1903-12-31', 1903, false, 'Konstantin Tsiolkovsky, a Russian schoolteacher, published the rocket equation and theoretical framework for space travel, including multi-stage rockets and space stations. He is considered the father of astronautics.', 'science', 'Europe', 0.65, 'Russia', 'Russian Empire', ST_SetSRID(ST_MakePoint(36.2612, 54.5138), 4326), 'approved', 'enrichment:space-astronomy'),
('goddard-first-liquid-fuel-rocket', 'Robert Goddard Launches First Liquid-Fuel Rocket', '1926-03-16', '1926-03-16', 1926, false, 'American physicist Robert Goddard launched the world''s first liquid-fueled rocket in Auburn, Massachusetts. The flight lasted 2.5 seconds and reached 41 feet, but proved the fundamental concept of liquid propulsion.', 'science', 'Americas', 0.70, 'United States', 'Interwar America', ST_SetSRID(ST_MakePoint(-71.8362, 42.1946), 4326), 'approved', 'enrichment:space-astronomy'),
('v2-rocket-ballistic-missile', 'V-2 Rocket Developed — First Ballistic Missile', '1944-09-08', '1944-09-08', 1944, false, 'Germany''s V-2 rocket, designed by Wernher von Braun, became the first long-range ballistic missile and first human-made object to reach space. After WWII, captured V-2 technology formed the basis of both US and Soviet rocket programs.', 'science', 'Europe', 0.75, 'Germany', 'Nazi Germany', ST_SetSRID(ST_MakePoint(13.7964, 54.1417), 4326), 'approved', 'enrichment:space-astronomy'),
('laika-first-animal-orbit', 'Laika — First Animal in Orbit', '1957-11-03', '1957-11-03', 1957, false, 'The Soviet Union launched Sputnik 2 carrying Laika, a stray dog from Moscow, making her the first animal to orbit Earth. The mission demonstrated that living organisms could survive launch and weightlessness.', 'science', 'Europe', 0.65, 'Russia', 'Soviet Union', ST_SetSRID(ST_MakePoint(63.3420, 45.9200), 4326), 'approved', 'enrichment:space-astronomy'),
('alan-shepard-first-american-space', 'Alan Shepard — First American in Space', '1961-05-05', '1961-05-05', 1961, false, 'Alan Shepard became the first American in space aboard Freedom 7, completing a 15-minute suborbital flight. The mission demonstrated American capability and boosted morale after Gagarin''s orbital flight weeks earlier.', 'political', 'Americas', 0.75, 'United States', 'Cold War America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('john-glenn-orbits-earth', 'John Glenn Orbits Earth', '1962-02-20', '1962-02-20', 1962, false, 'John Glenn became the first American to orbit Earth aboard Friendship 7, completing three orbits in nearly five hours. Glenn became a national hero and later served as a US Senator.', 'political', 'Americas', 0.70, 'United States', 'Cold War America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('tereshkova-first-woman-space', 'Valentina Tereshkova — First Woman in Space', '1963-06-16', '1963-06-16', 1963, false, 'Soviet cosmonaut Valentina Tereshkova became the first woman in space aboard Vostok 6, orbiting Earth 48 times over nearly three days. It would be 19 years before another woman flew to space.', 'political', 'Europe', 0.80, 'Russia', 'Soviet Union', ST_SetSRID(ST_MakePoint(63.3420, 45.9200), 4326), 'approved', 'enrichment:space-astronomy'),
('luna-9-first-moon-landing', 'Soviet Luna 9 — First Soft Landing on Moon', '1966-02-03', '1966-02-03', 1966, false, 'The Soviet Luna 9 spacecraft made the first successful soft landing on the Moon, transmitting the first photographs from the lunar surface. It proved the surface could support a lander.', 'science', 'Europe', 0.70, 'Russia', 'Soviet Union', ST_SetSRID(ST_MakePoint(63.3420, 45.9200), 4326), 'approved', 'enrichment:space-astronomy'),
('apollo-1-fire', 'Apollo 1 Fire — Three Astronauts Killed', '1967-01-27', '1967-01-27', 1967, false, 'A cabin fire during a launch rehearsal test killed astronauts Gus Grissom, Ed White, and Roger Chaffee. The tragedy led to major design and safety overhauls that ultimately made the Apollo program safer.', 'political', 'Americas', 0.65, 'United States', 'Cold War America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('apollo-8-first-lunar-orbit', 'Apollo 8 — First Humans Orbit the Moon', '1968-12-21', '1968-12-27', 1968, false, 'Apollo 8 became the first crewed spacecraft to leave low Earth orbit, orbit the Moon, and return safely. The mission produced the iconic "Earthrise" photograph that transformed humanity''s perspective.', 'science', 'Americas', 0.80, 'United States', 'Cold War America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('skylab-first-us-space-station', 'Skylab — First US Space Station', '1973-05-14', '1973-05-14', 1973, false, 'NASA launched Skylab, America''s first space station, which hosted three crews over 171 days. Astronauts conducted experiments in solar astronomy, Earth observation, and the effects of microgravity on the human body.', 'science', 'Americas', 0.65, 'United States', 'Cold War America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('viking-1-mars-landing', 'Viking 1 Lands on Mars', '1976-07-20', '1976-07-20', 1976, false, 'NASA''s Viking 1 became the first spacecraft to successfully land on Mars and perform its mission. It transmitted the first photographs from the Martian surface and conducted experiments searching for signs of life.', 'science', 'Americas', 0.75, 'United States', 'Cold War America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('mir-space-station', 'Mir Space Station Launched', '1986-02-20', '1986-02-20', 1986, false, 'The Soviet Union launched the Mir space station, which became the first long-term modular space station. Mir hosted international crews for 15 years and demonstrated long-duration human spaceflight capability.', 'science', 'Europe', 0.65, 'Russia', 'Soviet Union', ST_SetSRID(ST_MakePoint(63.3420, 45.9200), 4326), 'approved', 'enrichment:space-astronomy'),
('mars-pathfinder-sojourner', 'Mars Pathfinder and Sojourner Rover', '1997-07-04', '1997-07-04', 1997, false, 'NASA''s Mars Pathfinder mission deployed Sojourner, the first rover to operate on another planet. The low-cost mission demonstrated new landing techniques and captured public imagination with daily image transmissions.', 'science', 'Americas', 0.65, 'United States', 'Modern America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('iss-construction-begins', 'International Space Station Construction Begins', '1998-11-20', '1998-11-20', 1998, false, 'The first module of the International Space Station was launched, beginning the largest international cooperative project in space history. The ISS has been continuously inhabited since November 2000.', 'science', 'Global', 0.80, 'International', 'Modern Era', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('columbia-disaster', 'Space Shuttle Columbia Disaster', '2003-02-01', '2003-02-01', 2003, false, 'The Space Shuttle Columbia broke apart during re-entry, killing all seven crew members. Foam insulation damage during launch caused the catastrophe, leading to a two-year shuttle program suspension and eventual retirement.', 'political', 'Americas', 0.70, 'United States', 'Modern America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('cassini-reaches-saturn', 'Cassini Reaches Saturn', '2004-07-01', '2004-07-01', 2004, false, 'The Cassini-Huygens spacecraft entered Saturn''s orbit after a seven-year journey, beginning a 13-year mission that revolutionized understanding of Saturn, its rings, and moons including Titan and Enceladus.', 'science', 'Americas', 0.65, 'United States', 'Modern America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('new-horizons-pluto', 'New Horizons Launched — Pluto Mission', '2006-01-19', '2006-01-19', 2006, false, 'NASA launched New Horizons, the fastest spacecraft ever at launch, on a nine-year journey to Pluto. In 2015 it provided the first detailed images of Pluto and its moons, revealing a geologically active world.', 'science', 'Americas', 0.65, 'United States', 'Modern America', ST_SetSRID(ST_MakePoint(-80.6040, 28.6080), 4326), 'approved', 'enrichment:space-astronomy'),
('curiosity-rover-mars', 'Mars Curiosity Rover Lands', '2012-08-06', '2012-08-06', 2012, false, 'NASA''s Curiosity rover landed on Mars using an innovative sky crane system. The car-sized rover has been exploring Gale Crater since, finding evidence that Mars once had conditions suitable for microbial life.', 'science', 'Americas', 0.70, 'United States', 'Modern America', ST_SetSRID(ST_MakePoint(-118.1714, 34.2013), 4326), 'approved', 'enrichment:space-astronomy'),
('ligo-gravitational-waves', 'LIGO Detects Gravitational Waves', '2016-02-11', '2016-02-11', 2016, false, 'The LIGO observatory detected gravitational waves from colliding black holes, confirming Einstein''s century-old prediction. The discovery opened an entirely new way of observing the universe.', 'discovery', 'Americas', 0.85, 'United States', 'Modern America', ST_SetSRID(ST_MakePoint(-90.7742, 30.5633), 4326), 'approved', 'enrichment:space-astronomy'),
('first-black-hole-image', 'First Image of a Black Hole', '2019-04-10', '2019-04-10', 2019, false, 'The Event Horizon Telescope collaboration released the first direct image of a black hole, showing the supermassive black hole at the center of galaxy M87. The image required a network of radio telescopes spanning the globe.', 'discovery', 'Global', 0.80, 'International', 'Modern Era', ST_SetSRID(ST_MakePoint(0, 0), 4326), 'approved', 'enrichment:space-astronomy'),
('perseverance-ingenuity-mars', 'Mars Perseverance Rover and Ingenuity Helicopter', '2021-02-18', '2021-02-18', 2021, false, 'NASA''s Perseverance rover landed in Jezero Crater on Mars, accompanied by Ingenuity, the first powered aircraft to fly on another planet. Perseverance is collecting samples for future return to Earth.', 'science', 'Americas', 0.70, 'United States', 'Modern America', ST_SetSRID(ST_MakePoint(-118.1714, 34.2013), 4326), 'approved', 'enrichment:space-astronomy')
ON CONFLICT (slug) DO NOTHING;

-- CAUSALITY LINKS
WITH evt AS (
  SELECT id, title FROM events
)
INSERT INTO causality_links (cause_event_id, effect_event_id, link_type, strength, description, created_by, review_status)
SELECT c.id, e.id, v.link_type, v.strength, v.description, 'enrichment:space-astronomy', 'approved'
FROM (VALUES
  ('Copernicus Publishes Heliocentric Theory', 'Kepler''s Laws of Planetary Motion', 'direct', 0.85, 'Copernicus heliocentric model enabled Kepler to develop laws of planetary motion'),
  ('Copernicus Publishes Heliocentric Theory', 'Galileo Observes Jupiter''s Moons', 'direct', 0.80, 'Galileo''s observations provided empirical evidence for Copernican heliocentrism'),
  ('Kepler''s Laws of Planetary Motion', 'Newton''s Principia Mathematica — Laws of Motion and Gravity', 'direct', 0.90, 'Kepler''s laws were key data Newton explained with universal gravitation'),
  ('Newton''s Principia Mathematica — Laws of Motion and Gravity', 'Halley Predicts Comet Return', 'direct', 0.90, 'Halley used Newtonian gravity to calculate and predict comet orbits'),
  ('Tsiolkovsky Publishes Rocket Equation', 'Robert Goddard Launches First Liquid-Fuel Rocket', 'indirect', 0.60, 'Tsiolkovsky theoretical work preceded and paralleled Goddard practical rocketry'),
  ('Robert Goddard Launches First Liquid-Fuel Rocket', 'V-2 Rocket Developed — First Ballistic Missile', 'contributing', 0.70, 'Goddard liquid-fuel rocket research influenced German rocket development'),
  ('V-2 Rocket Developed — First Ballistic Missile', 'Soviet Sputnik Launches the Space Race', 'direct', 0.85, 'Captured V-2 technology and engineers formed basis of Soviet rocket programs'),
  ('V-2 Rocket Developed — First Ballistic Missile', 'NASA Founded — US Space Program Begins', 'indirect', 0.70, 'German rocket scientists like von Braun became core of US space program'),
  ('Soviet Sputnik Launches the Space Race', 'NASA Founded — US Space Program Begins', 'direct', 0.95, 'Sputnik shock directly led to creation of NASA'),
  ('Soviet Sputnik Launches the Space Race', 'Laika — First Animal in Orbit', 'direct', 0.85, 'Sputnik 2 with Laika launched one month after Sputnik 1'),
  ('NASA Founded — US Space Program Begins', 'Alan Shepard — First American in Space', 'direct', 0.90, 'NASA Mercury program put Shepard in space'),
  ('Yuri Gagarin — First Human in Space', 'Alan Shepard — First American in Space', 'direct', 0.80, 'Gagarin flight intensified urgency of US human spaceflight'),
  ('Alan Shepard — First American in Space', 'John Glenn Orbits Earth', 'direct', 0.85, 'Shepard suborbital flight led to Glenn full orbital mission'),
  ('Soviet Sputnik Launches the Space Race', 'Yuri Gagarin — First Human in Space', 'direct', 0.85, 'Soviet rocket program advanced from Sputnik to human spaceflight'),
  ('Yuri Gagarin — First Human in Space', 'Apollo 11 — First Moon Landing', 'direct', 0.90, 'Gagarin flight prompted Kennedy Moon commitment driving Apollo'),
  ('Apollo 1 Fire — Three Astronauts Killed', 'Apollo 8 — First Humans Orbit the Moon', 'direct', 0.75, 'Apollo 1 tragedy led to safety redesigns enabling successful missions'),
  ('Apollo 8 — First Humans Orbit the Moon', 'Apollo 11 — First Moon Landing', 'direct', 0.90, 'Apollo 8 validated lunar orbital procedures for Moon landing'),
  ('Apollo 11 — First Moon Landing', 'Skylab — First US Space Station', 'direct', 0.70, 'Apollo hardware and experience enabled Skylab development'),
  ('Space Shuttle Challenger Disaster', 'Hubble Space Telescope Launched', 'indirect', 0.55, 'Challenger delayed Hubble launch; safety reviews improved operations'),
  ('Skylab — First US Space Station', 'International Space Station Construction Begins', 'contributing', 0.65, 'Skylab experience informed ISS design and operations'),
  ('Mir Space Station Launched', 'International Space Station Construction Begins', 'direct', 0.80, 'Mir experience and US-Russian cooperation led directly to ISS'),
  ('Space Shuttle Columbia Disaster', 'SpaceX Lands Falcon 9 — Reusable Rockets Become Reality', 'indirect', 0.50, 'Shuttle disasters highlighted need for new approaches to space access'),
  ('SpaceX Lands Falcon 9 — Reusable Rockets Become Reality', 'SpaceX Crew Dragon — First Commercial Crewed Spaceflight', 'direct', 0.85, 'Falcon 9 success enabled SpaceX to develop crewed spacecraft')
) AS v(cause_title, effect_title, link_type, strength, description)
JOIN evt c ON c.title = v.cause_title
JOIN evt e ON e.title = v.effect_title
ON CONFLICT (cause_event_id, effect_event_id) DO NOTHING;
